node -e "
var fs = require('fs');
var path = require('path');
var file = process.env.CLAUDE_TOOL_INPUT_FILE_PATH || process.env.CLAUDE_FILE_PATH || '';
if (!file.endsWith('main.js')) process.exit(0);
try {
  var code = fs.readFileSync(file, 'utf8');
  var warns = [];
  if (/shadowBlur[^}]+for\s*\(|for\s*\([^)]+\)[^{]+{[^}]*shadowBlur/s.test(code)) warns.push('⚠ shadowBlur detectado dentro de un loop — esto destruye el rendimiento. Mueve ctx.shadowBlur fuera del loop.');
  if (/ctx\.fillText\([^)]*[\uD800-\uDFFF\u2600-\u27FF]/u.test(code)) warns.push('⚠ Posible emoji en ctx.fillText() — los emojis en canvas causan bugs de transparencia. Usa formas canvas en su lugar.');
  if (/setInterval.*draw|draw.*setInterval/s.test(code) && !/requestAnimationFrame/.test(code)) warns.push('⚠ Usando setInterval para el game loop — usa requestAnimationFrame para sincronizar con el monitor.');
  if (/Math\.random\(\)/.test(code)) {
    var lines = code.split('\n');
    var drawFn = false;
    lines.forEach(function(l,i) {
      if (/function\s+(draw|render|paint)/.test(l)) drawFn = true;
      if (drawFn && /Math\.random/.test(l)) warns.push('⚠ Math.random() en función de render (línea ' + (i+1) + ') — pre-computa valores aleatorios en spawn, no en cada frame.');
    });
  }
  if (!/(GameAudio|audio\.js)/.test(code) && /main\.js$/.test(file)) warns.push('ℹ audio.js no integrado — considera agregar sonidos con /add-sounds.');
  if (warns.length > 0) {
    console.log('\n🔍 Code Quality Check — ' + path.basename(file));
    warns.forEach(function(w) { console.log(w); });
  }
} catch(e) {}
"

node -e "
var fs = require('fs');
var path = require('path');
var file = process.env.CLAUDE_TOOL_INPUT_FILE_PATH || process.env.CLAUDE_FILE_PATH || '';
if (!file.endsWith('index.html')) process.exit(0);
try {
  var code = fs.readFileSync(file, 'utf8');
  var warns = [];
  var isCatalog = /games-grid/.test(code);
  if (isCatalog) {
    if (/img[^>]+\/image\.png/.test(code)) warns.push('⚠ El catálogo usa <img> para miniaturas — reemplaza con <canvas data-game=nombre> y thumbnails.js');
    if (/data-game=/.test(code) && !/thumbnails\.js/.test(code)) warns.push('⚠ canvas data-game= sin thumbnails.js — agrega <script src=./thumbnails.js> al final del body');
  }
  if (warns.length > 0) {
    console.log('\n🔍 Catalog Check — index.html');
    warns.forEach(function(w) { console.log(w); });
  }
} catch(e) {}
"

node -e "
var fs = require('fs');
