var file = process.env.CLAUDE_TOOL_INPUT_FILE_PATH || process.env.CLAUDE_FILE_PATH || '';
if (!file.endsWith('thumbnails.js')) process.exit(0);
try {
  var code = fs.readFileSync(file, 'utf8');
  var m = code.match(/[a-z0-9]+:\s*function\s*\(ctx\)/gi) || [];
  console.log('\nℹ thumbnails.js — ' + m.length + ' miniaturas definidas.');
} catch(e) {}
"
